+            <option value="Delivered">Delivered</option>
+        </select>
+    </div>
+</div>
+
+@if (shipments is null)
+{
+    <p><em>Loading shipments...</em></p>
+}
+else if (!FilteredShipments.Any())
+{
+    <p>No shipments match the current filter.</p>
+}
+else
+{
+    <div class="table-responsive">
+        <table class="table table-striped table-hover">
+            <thead>
+                <tr>
+                    <th>Tracking #</th>
+                    <th>Description</th>
+                    <th>Origin</th>
+                    <th>Destination</th>
+                    <th>Status</th>
+                    <th>Est. Delivery</th>
+                    <th>Actions</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var shipment in FilteredShipments)
+                {
+                    <tr>
+                        <td><code>@shipment.TrackingNumber</code></td>
+                        <td>@shipment.Description</td>
+                        <td>@shipment.Origin</td>
+                        <td>@shipment.Destination</td>
+                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
+                        <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
+                        <td>
+                            @if (shipment.Status != "Delivered")
+                            {
+                                <select class="form-select form-select-sm" style="width:auto;display:inline-block"
+                                        @onchange="(e) => UpdateStatus(shipment.Id, e.Value?.ToString() ?? string.Empty)">
+                                    <option value="" disabled selected>Change...</option>
+                                    <option value="Pending">Pending</option>
+                                    <option value="In Transit">In Transit</option>
+                                    <option value="Customs Hold">Customs Hold</option>
+                                    <option value="Delivered">Delivered</option>
+                                </select>
+                            }
+                            else
+                            {
+                                <span class="text-muted">Completed</span>
+                            }
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+}
+
+@if (!string.IsNullOrEmpty(errorMessage))
+{
+    <div class="alert alert-danger mt-3">@errorMessage</div>
+}
+
+@code {
+    private List<ShipmentDto>? shipments;
+    private string filterText = string.Empty;
+    private string statusFilter = string.Empty;
+    private string? errorMessage;
+
+    private IEnumerable<ShipmentDto> FilteredShipments =>
+        (shipments ?? []).Where(s =>
+            (string.IsNullOrEmpty(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
+            (string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter));
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            shipments = await ShipmentService.GetAllShipmentsAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load shipments: {ex.Message}";
+        }
+    }
+
+    private async Task UpdateStatus(int id, string newStatus)
+    {
+        if (string.IsNullOrEmpty(newStatus)) return;
+
+        try
+        {
+            errorMessage = null;
+            var updated = await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
+            var index = shipments!.FindIndex(s => s.Id == id);
+            if (index >= 0)
+                shipments[index] = updated;
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to update status: {ex.Message}";
+        }
+    }
+
+    private static string GetStatusBadgeClass(string status) => status switch
+    {
+        "Pending" => "bg-secondary",
+        "In Transit" => "bg-primary",
+        "Customs Hold" => "bg-warning text-dark",
+        "Delivered" => "bg-success",
+        _ => "bg-info"
+    };
+}
+

